<script setup>
import {ref} from 'vue';
import ChatIcon from './ChatIcon.vue';
defineProps({modelValue:String,disabled:Boolean,preview:String});
const emit=defineEmits(['update:modelValue','send','file','clear']);
const picker=ref(null),camera=ref(null),stickers=ref(false);
function choose(e){const file=e.target.files?.[0];if(file)emit('file',file);e.target.value='';}
</script>
<template><footer class="chat-input"><div v-if="preview" class="attachment"><img :src="preview" alt="Photo to send"><button @click="$emit('clear')" aria-label="Remove photo">×</button></div><div v-if="stickers" class="emoji-picker"><button v-for="emoji in ['👍','❤️','😂','🔥','💪','👋']" :key="emoji" @click="$emit('update:modelValue',modelValue+emoji);stickers=false">{{ emoji }}</button></div><form @submit.prevent="$emit('send')"><button type="button" class="attach" aria-label="Attach photo" :disabled="disabled" @click="picker.click()"><ChatIcon name="plus"/></button><div class="field"><input :value="modelValue" @input="$emit('update:modelValue',$event.target.value)" placeholder="Message" aria-label="Message" maxlength="2000" autocomplete="off" enterkeyhint="send" :disabled="disabled"><button type="button" aria-label="Choose emoji" :aria-expanded="stickers" :disabled="disabled" @click="stickers=!stickers"><ChatIcon name="sticker"/></button><button type="button" aria-label="Take a photo" :disabled="disabled" @click="camera.click()"><ChatIcon name="camera"/></button></div><button v-if="modelValue.trim()||preview" type="submit" class="send" aria-label="Send message" :disabled="disabled"><ChatIcon name="send"/></button><button v-else type="button" class="send" disabled aria-label="Voice messages unavailable" title="Voice messages are not available"><ChatIcon name="mic"/></button></form><input ref="picker" type="file" accept="image/jpeg,image/png,image/webp" hidden @change="choose"><input ref="camera" type="file" accept="image/*" capture="environment" hidden @change="choose"></footer></template>
<style scoped>
.chat-input{flex:none;position:relative;background:var(--card);padding:8px 8px calc(8px + var(--chat-bottom-safe-area,env(safe-area-inset-bottom,0px)))}.chat-input form{display:flex;align-items:center;gap:7px}.chat-input button{display:grid;place-items:center;background:none;border:0;color:var(--mute);cursor:pointer;padding:7px;min-height:40px;min-width:32px}.field{display:flex;align-items:center;flex:1;min-width:0;background:var(--soft);border-radius:12px;padding:2px 4px 2px 12px}.field input{width:100%;min-width:0;border:0!important;background:transparent!important;color:var(--ink);padding:8px 0;font-size:16px;outline-offset:0}.field input::placeholder{color:var(--mute)}.field button{padding:5px}.chat-input .send{width:44px;height:44px;min-width:44px;border-radius:12px;background:var(--cta);color:var(--on)}.chat-input .send:disabled{cursor:not-allowed;opacity:.75}.attachment{display:flex;align-items:center;gap:12px;padding:5px 40px}.attachment img{height:80px;border-radius:12px}.emoji-picker{position:absolute;bottom:100%;left:10px;right:10px;background:var(--soft);border-radius:12px;display:flex;justify-content:space-around;padding:10px;}.emoji-picker button{font-size:25px}
</style>

<style scoped>.field{border-radius:24px}.chat-input .send{border-radius:50%;background:var(--cta);color:var(--on)}.attachment img{border-radius:12px}</style>
<style scoped>
.chat-input .field input{border-radius:0;padding:8px 0;min-height:36px;font-size:16px;outline:none!important;box-shadow:none}
.chat-input .field:focus-within{outline:1px solid var(--green);outline-offset:-1px}
</style>
